//! The git of the rule of `generated_files`: the attributes of a revision, and the generated files both sides of an
//! update changed.

use crate::commit_files::MAX_BLOB_BYTES;
use crate::generated::{GeneratedFile, attribute_generated_paths, generated_paths, merged_generated_files};
use generated_files::generated_by::GeneratedBy;
use generated_files::names::GeneratedName;
use pretty_assertions::assert_eq;
use std::collections::HashSet;
use test_log::test;
use test_utils::git_test_utils::TestRepo;

fn set(paths: &[&str]) -> HashSet<String> {
  paths.iter().map(|path| (*path).to_string()).collect()
}

/// `linguist-generated` and `-diff` (which `binary` implies) of the revision, not of the working tree; the lock files by
/// their name
#[test]
fn the_attributes_of_the_revision_mark_generated_files_and_a_lock_file_is_one_by_its_name() {
  let repo = TestRepo::new();
  repo.create_commit(
    "attributes",
    ".gitattributes",
    "gen/** linguist-generated\n*.bin binary\nkept.json linguist-generated=false\n",
  );
  let first = repo.head();
  repo.create_commit("more", ".gitattributes", "gen/** linguist-generated\n*.bin binary\n*.json linguist-generated\n");
  let (git, path) = (repo.git_executor(), repo.path_str());
  let paths = ["gen/a.rs", "x.bin", "kept.json", "src/a.rs", "Cargo.lock"];
  assert_eq!(attribute_generated_paths(git, path, &first, paths).unwrap(), set(&["gen/a.rs", "x.bin"]));
  assert_eq!(attribute_generated_paths(git, path, "HEAD", paths).unwrap(), set(&["gen/a.rs", "x.bin", "kept.json"]));
  assert_eq!(generated_paths(git, path, &first, paths).unwrap(), set(&["gen/a.rs", "x.bin", "Cargo.lock"]));
  assert_eq!(generated_paths(git, path, "HEAD", ["Cargo.lock"]).unwrap(), set(&["Cargo.lock"]));
}

const HEADER: &str = "# Generated by `plans-tool` - do not edit.\n";

fn table(lines: &[&str]) -> String {
  format!("{HEADER}{}\n", lines.join("\n"))
}

/// A base, the upstream commit on it, and the update of the local commits onto the upstream (its files written as
/// given): `[base, upstream, new_head]`
fn updated(repo: &TestRepo, base: &[(&str, &str)], upstream: &[(&str, &str)], merged: &[(&str, &str)]) -> [String; 3] {
  let base = repo.create_commit_with_files("base", base);
  let upstream = repo.create_commit_with_files("Add a product upstream", upstream);
  let new_head = repo.create_commit_with_files("(plans) Split the old plan", merged);
  [base, upstream, new_head]
}

fn header() -> GeneratedBy {
  GeneratedBy::Header {
    line: "Generated by `plans-tool` - do not edit.".to_string(),
  }
}

/// Only a generated file that the upstream changed and the update changed again is a merge no generator wrote, whether
/// git merged it cleanly or not: a written file, a generated file of one side, the same change of both sides (the
/// update keeps the upstream's) and a file the update deleted are not
#[test]
fn the_generated_files_both_sides_changed_are_the_ones_to_regenerate() {
  let repo = TestRepo::new();
  repo.create_commit("attributes", ".gitattributes", "models/** linguist-generated\n");
  let [base, upstream, _] = updated(
    &repo,
    &[
      ("plans.bzl", &table(&["_PLAN_OLD = 1", "", "", "PLANS = {}"])),
      ("models/one.json", "{}\n"),
      ("same.bzl", &table(&["OLD = 1"])),
      ("src/main.txt", "main\n"),
      ("Cargo.lock", "lock\n"),
      ("gone.bzl", &table(&["GONE = 1"])),
    ],
    &[
      ("plans.bzl", &table(&["_PLAN_OLD = 1", "", "", "PLANS = {\"new\": _PLAN_OLD}"])),
      ("models/one.json", "{\"upstream\": 1}\n"),
      ("models/new.json", "{}\n"),
      ("same.bzl", &table(&["NEW = 1"])),
      ("src/main.txt", "upstream, main\n"),
      ("gone.bzl", &table(&["GONE = 3"])),
    ],
    &[
      ("plans.bzl", &table(&["_PLAN_A = 1", "", "", "PLANS = {\"new\": _PLAN_OLD}"])),
      ("models/one.json", "{\"block\": 1, \"upstream\": 1}\n"),
      ("src/main.txt", "upstream, main, local\n"),
      ("Cargo.lock", "lock, local\n"),
    ],
  );
  // a round deleted it
  repo.git(&["rm", "-q", "gone.bzl"]);
  repo.git(&["commit", "-qm", "(plans) Split the old plan, gone.bzl deleted"]);
  let new_head = repo.head();

  let git = repo.git_executor().with_process_stats("regenerate");
  let files = merged_generated_files(&git, repo.path_str(), &base, &upstream, &new_head, &[]).unwrap();
  assert_eq!(
    files,
    vec![
      GeneratedFile {
        path: "models/one.json".to_string(),
        generated_by: GeneratedBy::Attribute,
      },
      GeneratedFile {
        path: "plans.bzl".to_string(),
        generated_by: header(),
      },
    ]
  );
  assert_eq!(
    git.process_stats().unwrap().counts(),
    vec![("cat-file".to_string(), 1), ("check-attr".to_string(), 1), ("diff-tree".to_string(), 2)]
  );
}

/// A file a round took from `onto` is the upstream's in the new HEAD, but the local commit changed it: it is regenerated
/// too. A lock file is generated by its name; a fast-forward has no local side and costs nothing
#[test]
fn a_file_taken_from_onto_and_a_lock_file_are_regenerated_and_a_fast_forward_costs_no_process() {
  let repo = TestRepo::new();
  let [base, upstream, new_head] = updated(
    &repo,
    &[("Cargo.lock", "a\nb\nc\n"), ("plans.bzl", &table(&["OLD = 1"]))],
    &[("Cargo.lock", "a\nb\nC\n"), ("plans.bzl", &table(&["NEW = 1"]))],
    &[("Cargo.lock", "A\nb\nC\n")],
  );
  let regenerate = |taken_onto: &[String]| merged_generated_files(repo.git_executor(), repo.path_str(), &base, &upstream, &new_head, taken_onto).unwrap();
  let lock = GeneratedFile {
    path: "Cargo.lock".to_string(),
    generated_by: GeneratedBy::Name { name: GeneratedName::LockFile },
  };
  assert_eq!(regenerate(&[]), vec![lock.clone()]);
  let plans = GeneratedFile {
    path: "plans.bzl".to_string(),
    generated_by: header(),
  };
  assert_eq!(regenerate(&["plans.bzl".to_string()]), vec![lock, plans]);

  let git = repo.git_executor().with_process_stats("fast-forward");
  assert_eq!(merged_generated_files(&git, repo.path_str(), &base, &upstream, &upstream, &[]).unwrap(), Vec::new());
  assert_eq!(git.process_stats().unwrap().counts(), Vec::<(String, u32)>::new());
}

/// A generated file larger than the limit of the batch is told by the first bytes of its text, its header
#[test]
fn a_generated_file_over_the_limit_of_the_batch_is_told_by_its_header() {
  let repo = TestRepo::new();
  let large = |last: &str| format!("{HEADER}{}{last}\n", "x = 1\n".repeat(MAX_BLOB_BYTES / 6 + 1));
  let [base, upstream, new_head] = updated(&repo, &[("large.bzl", &large("a"))], &[("large.bzl", &large("b"))], &[("large.bzl", &large("c"))]);
  let files = merged_generated_files(repo.git_executor(), repo.path_str(), &base, &upstream, &new_head, &[]).unwrap();
  assert_eq!(
    files,
    vec![GeneratedFile {
      path: "large.bzl".to_string(),
      generated_by: header(),
    }]
  );
}
